#include "generated/symm/symm.h"


/* Array initialization. */
static
void init_array(int m, int n,
		DATA_TYPE *alpha,
		DATA_TYPE *beta,
		DATA_TYPE POLYBENCH_2D(C,M,N,m,n),
		DATA_TYPE POLYBENCH_2D(A,M,M,m,m),
		DATA_TYPE POLYBENCH_2D(B,M,N,m,n))
{
  int i, j;

  *alpha = 1.5;
  *beta = 1.2;
  for (i = 0; i < m; i++)
    for (j = 0; j < n; j++) {
      C[i][j] = (DATA_TYPE) ((i+j) % 100) / m;
      B[i][j] = (DATA_TYPE) ((n+i-j) % 100) / m;
    }
  for (i = 0; i < m; i++) {
    for (j = 0; j <=i; j++)
      A[i][j] = (DATA_TYPE) ((i+j) % 100) / m;
    for (j = i+1; j < m; j++)
      A[i][j] = -999; //regions of arrays that should not be used
  }
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int m, int n,
		 DATA_TYPE POLYBENCH_2D(C,M,N,m,n))
{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("C");
  for (i = 0; i < m; i++)
    for (j = 0; j < n; j++) {
	if ((i * m + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
	fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, C[i][j]);
    }
  POLYBENCH_DUMP_END("C");
  POLYBENCH_DUMP_FINISH;
}

/* Kernel implementation in Exo:
EXO START
from __future__ import annotations

from exo import *
from exo.libs.memories import DRAM
from exo.API_scheduling import *

# Column tile size for the j-dimension. Chosen to keep a strip of
# B[* , j] / C[* , j] / temp2[j] resident in cache on x64.
J_BLOCK = 64


@proc
def kernel_symm(
    m: size,
    n: size,
    alpha: DATA_TYPE,
    beta: DATA_TYPE,
    C: DATA_TYPE[m, n] @ DRAM,
    A: DATA_TYPE[m, m] @ DRAM,
    B: DATA_TYPE[m, n] @ DRAM,
):
    #
    # Pass 1: scale C by beta.
    #
    # In the original PolyBench-style kernel, each C[i, j] is multiplied
    # by beta exactly once, when processing row i, before any symmetric
    # contributions are added to that element. Performing this scaling
    # in a separate pass is algebraically identical:
    #
    #   C[i, j] <- beta * C0[i, j]
    #   C[i, j] <- C[i, j] + alpha * (... symmetric term ...)
    #
    # This exposes a pure accumulation pattern in the second pass and
    # improves opportunities for vectorization and parallelization.
    #
    for i in seq(0, m):
        for j in seq(0, n):
            C[i, j] = beta * C[i, j]

    #
    # Pass 2: symmetric matrix–matrix product
    #
    # Using only the lower triangle of A (k <= i), we implement:
    #
    #   C := C + alpha * A_sym * B
    #
    # where A_sym is the logical symmetric matrix defined by:
    #   A_sym[i, k] = A[i, k] if k <= i
    #               = A[k, i] if k >  i
    #
    # Algorithm (per row i):
    #
    #   temp2[j] = sum_{k < i} B[k, j] * A[i, k]
    #
    #   For k < i:
    #     - update row k of C using A[i, k] and B[i, j]
    #     - accumulate temp2[j] using A[i, k] and B[k, j]
    #
    #   Then:
    #     C[i, j] += alpha * (A[i, i] * B[i, j] + temp2[j])
    #
    # This is algebraically equivalent to the original Exo kernel:
    #   C[i, j] = beta * C0[i, j]
    #             + alpha * sum_{k} A_sym[i, k] * B[k, j]
    #
    # Only A[i, k] with k <= i are ever read, so the -999 upper-triangular
    # sentinels written in init_array are never used.
    #
    for i in seq(0, m):
        # Per-row scratch: temp2[j] holds sum_{k < i} B[k, j] * A[i, k].
        # Size is n, so the extra storage is O(n) (well under +50% of the
        # original footprint A: m^2, B: m*n, C: m*n).
        temp2: DATA_TYPE[n]

        # Initialize temp2 for this row i.
        for j in seq(0, n):
            temp2[j] = 0

        # Accumulate strictly lower-triangular contributions (k < i).
        for k in seq(0, i):
            # Hoist A[i, k] into a scalar so it is loaded once per (i, k)
            # and reused across all columns j.
            a_ik: DATA_TYPE
            a_ik = A[i, k]

            # Traverse columns in J_BLOCK-sized tiles so that, for each
            # fixed (i, k), we touch:
            #   - C[k, j],
            #   - B[i, j], B[k, j],
            #   - temp2[j]
            # in contiguous chunks along the row-major j dimension.
            for jb in seq(0, (n + J_BLOCK - 1) / J_BLOCK):
                for jj in seq(0, J_BLOCK):
                    if jb * J_BLOCK + jj < n:
                        C[k, jb * J_BLOCK + jj] += alpha * B[i, jb * J_BLOCK + jj] * a_ik
                        temp2[jb * J_BLOCK + jj] += B[k, jb * J_BLOCK + jj] * a_ik

        # Finish row i: add the diagonal term and the accumulated symmetric
        # contributions stored in temp2.
        for jb in seq(0, (n + J_BLOCK - 1) / J_BLOCK):
            for jj in seq(0, J_BLOCK):
                if jb * J_BLOCK + jj < n:
                    C[i, jb * J_BLOCK + jj] += alpha * (
                        B[i, jb * J_BLOCK + jj] * A[i, i]
                        + temp2[jb * J_BLOCK + jj]
                    )


# --------------------------
# Simple schedule:
# --------------------------
# Parallelize the first i-loop (beta scaling of C). Each (i, j) element
# is updated exactly once in that loop, with no cross-iteration
# dependencies, so it is safe to run iterations in parallel. The second
# pass has more intricate dependencies along i and k, so we leave it
# sequential and rely on the improved cache behavior and contiguous
# j-access pattern in the inner loops.
loop_i0 = kernel_symm.find_loop("i")
kernel_symm = parallelize_loop(kernel_symm, loop_i0)
