    #
    # Semantics: matches the PolyBench SYMM kernel and the original Exo version.
    # For each row i and column j:
    #   temp2 = sum_{k=0..i-1} B[k, j] * A[i, k]
    #   C[k, j] += alpha * B[i, j] * A[i, k]   for all k < i
    #   C[i, j]  = beta * C[i, j] \
    #              + alpha * B[i, j] * A[i, i] \
    #              + alpha * temp2
